KG42.register("rules-b6ff80b083d5848db1708afc",{"id":"28-multiclass_prosumer_preferences::v141-c-R010","paper":"28-multiclass_prosumer_preferences","record":{"rule_id":"v141-c-R010","mechanism_id":"v141-a-M01","name":"Local energy product","process_stage":"clearing","market_meaning":"Each unit of energy is assigned an energy class according to relevant source attributes; energy is treated as a heterogeneous product based on source attributes valued by prosumers. Scope: Energy within the distribution network served by the proposed P2P platform. The prosumer may use the energy class to supply its loads. Scope: Energy-class use for supplying each prosumer's loads. Condition: The energy class belongs to that prosumer's allowed load-supply class set. The energy class may be substituted for and stored as grid energy. Scope: Substitution and storage of energy classes as grid energy in the multiclass platform. Condition: The energy class belongs to the designated permitted substitution/storage subset. The amount of that energy class stored as grid energy must be zero. Scope: Substitution and storage of energy classes as grid energy at every interval of the MPC time horizon. Condition: The energy class is outside the permitted substitution/storage subset. The case study defines three energy classes based on prosumer preferences: grid energy, green energy and subsidised energy. Scope: IEEE European Low Voltage Test Feeder case study with 55 prosumers. Green energy may be substituted for and stored or sold as grid energy. Scope: Green energy in the IEEE European Low Voltage Test Feeder case study. Condition: Green energy is traded at a premium in this case study. Only low-income households may use subsidised energy. Scope: Subsidised energy in the IEEE European Low Voltage Test Feeder case study.","independence_rationale":"Relations governed by the approved function product.local_energy under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["product.local_energy"],"E":[],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"clearing","context_text":"Energy within the distribution network served by the proposed P2P platform. | Energy-class use for supplying each prosumer's loads. | Green energy in the IEEE European Low Voltage Test Feeder case study. | IEEE European Low Voltage Test Feeder case study with 55 prosumers. | Subsidised energy in the IEEE European Low Voltage Test Feeder case study. | Substitution and storage of energy classes as grid energy at every interval of the MPC time horizon. | Substitution and storage of energy classes as grid energy in the multiclass platform.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-G01-E20","v141-b-G01-E24","v141-b-G01-E25","v141-b-g01-E06","v141-b-g02-e027","v141-b-g03-e01"]},"x":[{"variable_id":"v141-c-R010-x-zik","symbol":"z_{ik}^{(t)}","meaning":"Average allocated load power of energy class k supplied to prosumer i at interval t.","kind":"operational","domain":"nonnegative real (0 \u003c= z_{ik}^{(t)}) for i in N, k in K, t in T","unit":"power","indices":["i","k","t"],"evidence_ids":["v141-b-g01-E14","v141-b-G01-E20","v141-b-g02-e005"]},{"variable_id":"v141-c-R010-x-zig","symbol":"z_{ig}^{(t)}","meaning":"Average allocated load power of grid energy supplied to prosumer i at interval t.","kind":"operational","domain":"nonnegative real (0 \u003c= z_{ig}^{(t)}) for i in N, t in T","unit":"power","indices":["i","t"],"evidence_ids":["v141-b-g01-E14","v141-b-G01-E20","v141-b-g02-e005"]},{"variable_id":"v141-c-R010-x-bikg","symbol":"b_{ikg}^{(t)}","meaning":"Amount of class k energy stored as grid energy at interval t, as used in the battery-output vector.","kind":"operational","domain":"nonnegative real for k in K_g; equal to 0 for k in K set-minus K_g, for i in N, t in T","unit":null,"indices":["i","k","t"],"evidence_ids":["v141-b-G01-E24","v141-b-G01-E25","v141-b-g02-e009","v141-b-g02-e010"]}],"theta":[{"parameter_id":"v141-c-R010-p-zpred","symbol":"z_i^{pred(t)}","meaning":"Predicted load power of prosumer i at interval t.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"power","indices":["i","t"],"evidence_ids":["v141-b-G01-E20"]},{"parameter_id":"v141-c-R010-p-Ki","symbol":"\\mathcal{K}_i","meaning":"Set of energy classes that prosumer i is allowed to use to supply its loads.","value":{"kind":"symbolic","number_value":null,"text_value":"\\mathcal{K}_i \\subseteq \\mathcal{K}"},"unit":null,"indices":["i"],"evidence_ids":["v141-b-G01-E20"]},{"parameter_id":"v141-c-R010-p-Kg","symbol":"\\mathcal{K}_g","meaning":"Set of energy classes allowed to be substituted for and stored as grid energy.","value":{"kind":"symbolic","number_value":null,"text_value":"\\mathcal{K}_g \\subseteq \\mathcal{K}"},"unit":null,"indices":[],"evidence_ids":["v141-b-G01-E24"]}],"phi":[{"constraint_id":"v141-c-R010-C001","kind":"procedural","role":"core","statement":"Each unit of energy is assigned an energy class according to relevant source attributes; energy is treated as a heterogeneous product based on source attributes valued by prosumers. Scope: Energy within the distribution network served by the proposed P2P platform.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["product.local_energy"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E06","v141-b-g03-e01"]},{"constraint_id":"v141-c-R010-C002","kind":"mathematical","role":"core","statement":"The prosumer may use the energy class to supply its loads. Scope: Energy-class use for supplying each prosumer's loads. Condition: The energy class belongs to that prosumer's allowed load-supply class set.","expression":"\\sum_{k\\in\\mathcal{K}_i} z_{ik}^{(t)} + z_{ig}^{(t)} = z_i^{\\mathrm{pred}(t)},\\; \\forall t\\in\\mathcal{T};\\quad 0\\le z_{ig}^{(t)},\\; 0\\le z_{ik}^{(t)},\\; \\forall k\\in\\mathcal{K},\\; \\forall t\\in\\mathcal{T}.","formalization_origin":"source","template_id":null,"members":["product.local_energy"],"variable_refs":["v141-c-R010-x-zik","v141-c-R010-x-zig"],"parameter_refs":["v141-c-R010-p-zpred","v141-c-R010-p-Ki"],"evidence_ids":["v141-b-G01-E20","v141-b-g02-e005"]},{"constraint_id":"v141-c-R010-C003","kind":"mathematical","role":"core","statement":"The energy class may be substituted for and stored as grid energy. Scope: Substitution and storage of energy classes as grid energy in the multiclass platform. Condition: The energy class belongs to the designated permitted substitution/storage subset.","expression":"0 \\le b_{ikg}^{(t)},\\quad \\forall k\\in\\mathcal{K}_g,\\; \\forall t\\in\\mathcal{T}.","formalization_origin":"source","template_id":null,"members":["product.local_energy"],"variable_refs":["v141-c-R010-x-bikg"],"parameter_refs":["v141-c-R010-p-Kg"],"evidence_ids":["v141-b-G01-E24","v141-b-G01-E25","v141-b-g02-e009","v141-b-g02-e010"]},{"constraint_id":"v141-c-R010-C004","kind":"mathematical","role":"core","statement":"The amount of that energy class stored as grid energy must be zero. Scope: Substitution and storage of energy classes as grid energy at every interval of the MPC time horizon. Condition: The energy class is outside the permitted substitution/storage subset.","expression":"b_{ikg}^{(t)} = 0,\\quad \\forall k\\in\\mathcal{K}\\setminus\\mathcal{K}_g,\\; \\forall t\\in\\mathcal{T}.","formalization_origin":"source","template_id":null,"members":["product.local_energy"],"variable_refs":["v141-c-R010-x-bikg"],"parameter_refs":["v141-c-R010-p-Kg"],"evidence_ids":["v141-b-G01-E24","v141-b-G01-E25","v141-b-g02-e010"]},{"constraint_id":"v141-c-R010-C005","kind":"procedural","role":"core","statement":"The case study defines three energy classes based on prosumer preferences: grid energy, green energy and subsidised energy. Scope: IEEE European Low Voltage Test Feeder case study with 55 prosumers.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["product.local_energy"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e027"]},{"constraint_id":"v141-c-R010-C006","kind":"procedural","role":"core","statement":"Green energy may be substituted for and stored or sold as grid energy. Scope: Green energy in the IEEE European Low Voltage Test Feeder case study. Condition: Green energy is traded at a premium in this case study.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["product.local_energy"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e027"]},{"constraint_id":"v141-c-R010-C007","kind":"procedural","role":"core","statement":"Only low-income households may use subsidised energy. Scope: Subsidised energy in the IEEE European Low Voltage Test Feeder case study.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["product.local_energy"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e027"]}],"pi":[{"evidence_id":"v141-b-G01-E20","location":{"location_id":"src-96285c344a-p04-c2r1__v141-a-M01-clearing","page":4,"printed_page":null,"section":"III. Multi-class Energy Management","anchor_text":"IEEE TRANSACTIONS ON POWER SYSTEMS, VOL. 34, NO. 5, SEPTEMBER 2019 reserved for low-income household","equation_id":"(7)-(8)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"Also, each prosumer, i \\in \\mathcal{N}, has load constraints, renewable generation constraints and battery constraints. The prosumer load constraints require that the total power allocated to its load meets its load predictions, z_i^{pred(t)}, \\forall t \\in \\mathcal{T}. Let \\mathcal{K}_i \\subseteq \\mathcal{K} be the set of energy classes that prosumer i is allowed to use to supply its loads (e.g., in the example from Fig. 1, subsidised energy is reserved for low-income households). \\sum_{k \\in \\mathcal{K}_i} z_{ik}^{(t)} + z_{ig}^{(t)} = z_i^{pred(t)}, \\forall t \\in \\mathcal{T}. \\quad 0 \\le z_{ig}^{(t)}, 0 \\le z_{ik}^{(t)}, \\forall k \\in \\mathcal{K}, \\forall t \\in \\mathcal{T}."},{"evidence_id":"v141-b-G01-E24","location":{"location_id":"src-96285c344a-p04-c2r4__v141-a-M01-clearing","page":4,"printed_page":null,"section":"III. Multi-class Energy Management","anchor_text":"The following additional constraints are needed since nega- tive SoC levels are not allowed. tch the","equation_id":"(13)-(14)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"The following additional constraints are needed since negative SoC levels are not allowed. \\mathbf{0} \\le s_{ik}^{(t_0)} \\mathbf{1} + A_{bi}(\\mathbf{b}_{ik} + \\mathbf{b}_{ikg}), \\forall k \\in \\mathcal{K}, \\forall t \\in \\mathcal{T}, \\quad \\mathbf{0} \\le s_{ig}^{(t_0)} \\mathbf{1} + A_{bi}\\left(\\mathbf{b}_{ig} - \\sum_{k \\in \\mathcal{K}} \\mathbf{b}_{ikg}\\right), \\forall t \\in \\mathcal{T}. \\quad \\mathbf{0} \\text{ is a vector with } |\\mathcal{T}| \\text{ elements, all equal to 0}. In (13), (14), \\mathbf{b}_{ikg} = [b_{ikg}^{(t_0)} \\cdots b_{ikg}^{(T)}]^T, where b_{ikg}^{(t)}, t \\in \\mathcal{T} is the amount of class k energy stored as grid energy. Certain energy classes, k \\in \\mathcal{K}_g \\subseteq \\mathcal{K}, are allowed to be substituted for and stored as grid energy (e.g., in the example from Fig. 1, green energy is traded at a premium and therefore may be substituted for grid energy)."},{"evidence_id":"v141-b-G01-E25","location":{"location_id":"src-96285c344a-p05-c1r1__v141-a-M01-clearing","page":5,"printed_page":null,"section":"III. Multi-class Energy Management","anchor_text":"MORSTYN AND MCCULLOCH: MULTICLASS ENERGY MANAGEMENT FOR PEER-TO-P energy classes that can be substit","equation_id":"(15)-(16)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"The following constraints are introduced to restrict the energy classes that can be substituted and stored as grid energy. 0 \\le b_{ikg}^{(t)}, \\forall k \\in \\mathcal{K}_g, \\forall t \\in \\mathcal{T}, \\quad b_{ikg}^{(t)} = 0, \\forall k \\in \\mathcal{K} \\setminus \\mathcal{K}_g, \\forall t \\in \\mathcal{T}."},{"evidence_id":"v141-b-g01-E06","location":{"location_id":"src-96285c344a-p02-c2r3__v141-a-M01-participation","page":2,"printed_page":null,"section":"II. Principle of Operation","anchor_text":"M. ences. For example: r Prosumers may prefer to obtain the best ﬁnancial return, ws regardless of t","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"It is assumed the prosumers have individual energy preferences. For example: Prosumers may prefer to obtain the best financial return, regardless of the source/destination of their energy. Prosumers may prefer to obtain energy from local sources or particular generation technologies. Prosumers may prefer to trade energy with particular subscribers (e.g., friends/relatives, low-income residents, community organisations). To account for the prosumers’ heterogeneous preferences, each unit of energy in the distribution network is assigned an ‘energy class’ relating to relevant attributes of its source. The prosumer preferences are incorporated into the proposed P2P market platform through utility functions (envisaged as being set by users), giving their additional willingness to pay to obtain, or to supply, energy with these attributes. Prosumers wishing only to obtain the best financial return would set their utility functions for each class of energy to zero."},{"evidence_id":"v141-b-g02-e027","location":{"location_id":"src-96285c344a-p06-c2r3__v141-a-M01-participation","page":6,"printed_page":null,"section":"V. Results","anchor_text":"and average resistance between the prosumers and main grid of Rg = 0.084Ω are used. t.) There are th","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"example"},"source_text":"The operation of the proposed P2P energy market platform based on multi-class energy management was verified using the IEEE European Low Voltage Test Feeder [42], with 55 prosumers. ... There are three types of prosumers in the distribution network, ‘green prosumers’, ‘philanthropic prosumers’ and ‘low-income households’. Based on their preferences, three energy classes are introduced; ‘grid energy’, ‘green energy’ and ‘subsidised energy’. Grid energy, is traded with the wholesale market at five minute trading intervals through the platform agent. Green energy is traded at a premium, so it is allowed to be substituted for and stored/sold as grid energy. Only low-income households are allowed to use subsidised energy."},{"evidence_id":"v141-b-g03-e01","location":{"location_id":"src-96285c344a-p08-c2r3__v141-a-M01-activation","page":8,"printed_page":null,"section":"VI. Conclusion","anchor_text":"product, based on attributes of its source that are perceived by prosumers to have value. This has b","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"restatement"},"source_text":"The new concept of multi-class energy management has been presented, which allows energy to be treated as a heterogeneous product, based on attributes of its source that are perceived by prosumers to have value."},{"evidence_id":"v141-b-g01-E14","location":{"location_id":"src-96285c344a-p03-c2r3__v141-a-M01-clearing","page":3,"printed_page":null,"section":"III. Multi-class Energy Management","anchor_text":"a t0 until the next full 2 hour interval and {t0 + 2, . . . , T} are the s, remaining full 2 hour in","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"For prosumer i \\in \\mathcal{N}, time interval t \\in \\mathcal{T} and energy class k \\in \\mathcal{K}; y_{ik}^{(t)} is the average renewable source output power, b_{ik}^{(t)} is the average battery output power, z_{ik}^{(t)} is the average allocated load power and x_{ik}^{(t)} is the average net power supplied to the prosumer. For grid class energy, the renewable generation export, average battery output power, allocated load power and net supplied power are y_{ig}^{(t)}, b_{ig}^{(t)}, z_{ig}^{(t)} and x_{ig}^{(t)}."},{"evidence_id":"v141-b-g02-e005","location":{"location_id":"src-96285c344a-p04-c2r1__v141-a-M01-clearing","page":4,"printed_page":null,"section":"III. Multi-class Energy Management","anchor_text":"IEEE TRANSACTIONS ON POWER SYSTEMS, VOL. 34, NO. 5, SEPTEMBER 2019 reserved for low-income household","equation_id":"(7)-(8)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"The prosumer load constraints require that the total power allocated to its load meets its load predictions, \\(z_i^{pred(t)}\\), \\(\\forall t\\in\\mathcal T\\). Let \\(\\mathcal K_i\\subseteq\\mathcal K\\) be the set of energy classes that prosumer \\(i\\) is allowed to use to supply its loads (e.g., in the example from Fig. 1, subsidised energy is reserved for low-income households). \\[ \\sum_{k\\in\\mathcal K_i} z_{ik}^{(t)} + z_{ig}^{(t)} = z_i^{pred(t)}, \\quad \\forall t\\in\\mathcal T. \\tag{7} \\] \\[ 0\\le z_{ig}^{(t)},\\quad 0\\le z_{ik}^{(t)},\\quad \\forall k\\in\\mathcal K,\\ \\forall t\\in\\mathcal T. \\tag{8} \\]"},{"evidence_id":"v141-b-g02-e009","location":{"location_id":"src-96285c344a-p04-c2r4__v141-a-M01-clearing","page":4,"printed_page":null,"section":"III. Multi-class Energy Management","anchor_text":"The following additional constraints are needed since nega- tive SoC levels are not allowed. tch the","equation_id":"(13)-(14)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"The following additional constraints are needed since negative SoC levels are not allowed. \\[ \\mathbf 0 \\le s_{ik}^{(t_0)}\\mathbf 1 + A_{bi}(\\mathbf b_{ik}+\\mathbf b_{ikg}),\\quad \\forall k\\in\\mathcal K,\\ \\forall t\\in\\mathcal T, \\tag{13} \\] \\[ \\mathbf 0 \\le s_{ig}^{(t_0)}\\mathbf 1 + A_{bi}\\left(\\mathbf b_{ig}-\\sum_{k\\in\\mathcal K}\\mathbf b_{ikg}\\right),\\quad \\forall t\\in\\mathcal T. \\tag{14} \\] \\(\\mathbf 0\\) is a vector with \\(|\\mathcal T|\\) elements, all equal to 0. In (13), (14), \\(\\mathbf b_{ikg}=[b_{ikg}^{(t_0)}\\ \\cdots\\ b_{ikg}^{(T)}]^{\\mathsf T}\\), where \\(b_{ikg}^{(t)}, t\\in\\mathcal T\\) is the amount of class \\(k\\) energy stored as grid energy. Certain energy classes, \\(k\\in\\mathcal K_g\\subseteq\\mathcal K\\), are allowed to be substituted for and stored as grid energy (e.g., in the example from Fig. 1, green energy is traded at a premium and therefore may be substituted for grid energy)."},{"evidence_id":"v141-b-g02-e010","location":{"location_id":"src-96285c344a-p05-c1r1__v141-a-M01-clearing","page":5,"printed_page":null,"section":"III. Multi-class Energy Management","anchor_text":"MORSTYN AND MCCULLOCH: MULTICLASS ENERGY MANAGEMENT FOR PEER-TO-P energy classes that can be substit","equation_id":"(15)-(16)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"The following constraints are introduced to restrict the energy classes that can be substituted and stored as grid energy. \\[ 0\\le b_{ikg}^{(t)},\\quad \\forall k\\in\\mathcal K_g,\\ \\forall t\\in\\mathcal T, \\tag{15} \\] \\[ b_{ikg}^{(t)}=0,\\quad \\forall k\\in\\mathcal K\\setminus\\mathcal K_g,\\ \\forall t\\in\\mathcal T. \\tag{16} \\]"}],"field_notes":{"empty_E_reason":"C explicitly supplied only source-backed unary facts for this function; other graph gaps remain reviewable.","empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-clearing","v141-a-M01-participation","v141-a-M01-pricing"],"extras":{"decision_anchor":"product.local_energy","graph_fact_supports":[[{"evidence_id":"v141-b-g01-E06","quote":"To account for the prosumers’ heterogeneous preferences, each unit of energy in the distribution network is assigned an ‘energy class’ relating to relevant attributes of its source."},{"evidence_id":"v141-b-g03-e01","quote":"The new concept of multi-class energy management has been presented, which allows energy to be treated as a heterogeneous product, based on attributes of its source that are perceived by prosumers to have value."}],[{"evidence_id":"v141-b-G01-E20","quote":"Let \\mathcal{K}_i \\subseteq \\mathcal{K} be the set of energy classes that prosumer i is allowed to use to supply its loads (e.g., in the example from Fig. 1, subsidised energy is reserved for low-income households)."}],[{"evidence_id":"v141-b-G01-E24","quote":"Certain energy classes, k \\in \\mathcal{K}_g \\subseteq \\mathcal{K}, are allowed to be substituted for and stored as grid energy"}],[{"evidence_id":"v141-b-G01-E24","quote":"where b_{ikg}^{(t)}, t \\in \\mathcal{T} is the amount of class k energy stored as grid energy."},{"evidence_id":"v141-b-G01-E25","quote":"b_{ikg}^{(t)} = 0, \\forall k \\in \\mathcal{K} \\setminus \\mathcal{K}_g, \\forall t \\in \\mathcal{T}."}],[{"evidence_id":"v141-b-g02-e027","quote":"Based on their preferences, three energy classes are introduced; ‘grid energy’, ‘green energy’ and ‘subsidised energy’."}],[{"evidence_id":"v141-b-g02-e027","quote":"Green energy is traded at a premium, so it is allowed to be substituted for and stored/sold as grid energy."}],[{"evidence_id":"v141-b-g02-e027","quote":"Only low-income households are allowed to use subsidised energy."}]],"C2_formalization":{"graph_sha256":"3134c1b03dac3da9cd230fa88577ba7b89ffc6d3933a9fdcfa16a4c3ed48dcee","applicability":"formalized","reason":"Partial formalization: C002-C004 are transcribed from the source load-class and grid-energy substitution/storage constraints (equations (7)-(8) and (15)-(16)). C001 and C005-C007 remain qualitative/procedural because the supplied text defines the energy-class product concept and case-study classes but does not state further formulas. The frozen rule graph contains only product.local_energy and no edges; all new variables, parameters and formalized constraints are bound to that node. B evidence remains unreviewed and no independent source audit is claimed.","bindings":[{"object_id":"v141-c-R010-x-zik","node_ids":["product.local_energy"],"edge_ids":[],"rationale":"z_{ik}^{(t)} is the class-specific load allocation through which an energy class is used to supply a prosumer's load; it binds to the local energy product node. The frozen rule has no edges."},{"object_id":"v141-c-R010-x-zig","node_ids":["product.local_energy"],"edge_ids":[],"rationale":"z_{ig}^{(t)} is the grid-energy load allocation appearing in the same energy-class load-supply constraint; it binds to the local energy product node. The frozen rule has no edges."},{"object_id":"v141-c-R010-x-bikg","node_ids":["product.local_energy"],"edge_ids":[],"rationale":"b_{ikg}^{(t)} is the amount of a class-specific energy product stored as grid energy; it binds directly to the local energy product node. The frozen rule has no edges."},{"object_id":"v141-c-R010-p-zpred","node_ids":["product.local_energy"],"edge_ids":[],"rationale":"z_i^{pred(t)} is the predicted load input in the class-based load-supply constraint for the local energy product."},{"object_id":"v141-c-R010-p-Ki","node_ids":["product.local_energy"],"edge_ids":[],"rationale":"\\mathcal{K}_i is the source-defined allowed load-supply class set constraining use of the local energy product."},{"object_id":"v141-c-R010-p-Kg","node_ids":["product.local_energy"],"edge_ids":[],"rationale":"\\mathcal{K}_g is the source-defined permitted substitution/storage subset for converting class energy into grid energy."},{"object_id":"v141-c-R010-C002","node_ids":["product.local_energy"],"edge_ids":[],"rationale":"The constraint formalizes the source requirements that class-based allocated load plus grid-class load meet predicted load and that allocated class loads be nonnegative; it binds to product.local_energy. No edge exists in the frozen rule."},{"object_id":"v141-c-R010-C003","node_ids":["product.local_energy"],"edge_ids":[],"rationale":"The constraint formalizes the nonnegative amount of class energy that may be stored as grid energy for classes in K_g; it binds to product.local_energy."},{"object_id":"v141-c-R010-C004","node_ids":["product.local_energy"],"edge_ids":[],"rationale":"The constraint formalizes that classes outside K_g have zero amount stored as grid energy; it binds to product.local_energy."}],"revision_requests":[]}},"quarantined_references":[]}});
